//! The models.dev catalog: what one model's window, output ceiling, modalities, thinking levels
//! and prices are, read from the compact snapshot the build ships with (or the one a newer
//! install refreshed into the data directory).
//!
//! `fold` — the other direction, turning `https://models.dev/api.json` into that snapshot — is
//! not wired here yet: the snapshot is generated by the Electron repo's `pnpm sync:models` and
//! shared by both apps, and nothing in this crate refreshes it on its own.

pub mod meta;

pub use meta::{
    Catalog, InputModality, ModelMeta, Price, PriceTier, default_context_window, default_meta,
    load_catalog,
};
